import {simulateMonth,decide} from './engine.js';
import {buildEndingCV,renderCV,validateCVModel} from './cv.js';
self.onmessage=e=>{const {id,type,state,plan,options,choice,model}=e.data;try{if(type==='cv'){self.postMessage({id,result:buildEndingCV(state)});return;}if(type==='cv-render'){if(!validateCVModel(model))throw new Error('Invalid CV model');self.postMessage({id,result:{model,html:renderCV(model)}});return;}if(type!=='month'&&type!=='decision')throw new Error('Unknown simulation operation');const next=type==='month'?simulateMonth(state,plan,options):decide(state,choice);self.postMessage({id,state:next});}catch(error){self.postMessage({id,error:error.message});}};
